import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"環境保護法","description":"","frontmatter":{},"headers":[],"relativePath":"ja/0046-环境保护法.md","filePath":"ja/0046-环境保护法.md"}'),e={name:"ja/0046-环境保护法.md"};function i(o,t,h,n,s,b){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="環境保護法" tabindex="-1">環境保護法 <a class="header-anchor" href="#環境保護法" aria-label="Permalink to &quot;環境保護法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>プロジェクト</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>46</td></tr><tr><td>所属モジュール</td><td>法律体系と統治枠組み</td></tr><tr><td>コアキーワード</td><td>環境保護、宇宙本源、生態共生、持続可能な発展、汚染防止と制御</td></tr></tbody></table><h2 id="第一節-立法目的と基本原則" tabindex="-1">第一節 立法目的と基本原則 <a class="header-anchor" href="#第一節-立法目的と基本原則" aria-label="Permalink to &quot;第一節 立法目的と基本原則&quot;">​</a></h2><p>《環境保護法》はアンカー共生文明の五部の付帯法の一つであり、衡元宙の生態環境と宇宙本源を保護し、「共生進化、持続可能な発展」の環境統治理念を確立し、略奪式開発による宇宙生態系の破壊を防止し、万族共進のために生存の根基を守ることを目的とする。</p><p>本法は以下の基本原則を確立する：</p><table tabindex="0"><thead><tr><th>原則</th><th>内包</th></tr></thead><tbody><tr><td>本源保護原則</td><td>宇宙本源はすべての生命と進化の根基であり、優先的に保護しなければならず、破壊的採掘を禁止する</td></tr><tr><td>生態共生原則</td><td>人間と自然、各族と生態系は共生関係にあり、生態を破壊することは自身の生存基礎を破壊することである</td></tr><tr><td>持続可能原則</td><td>すべての開発活動は現代と後代の利益を両立させなければならず、涸渇的漁獲に反対する</td></tr><tr><td>予防主原則</td><td>環境保護は予防を主とし、環境影響評価制度を構築し、汚染の発生を防止する</td></tr><tr><td>汚染者責任原則</td><td>環境汚染と生態破壊を引き起こした主体は治理と賠償の責任を負わなければならない</td></tr><tr><td>公衆参与原則</td><td>公衆の環境保護への参与を奨励し、公衆の環境知情権と参与権を保障する</td></tr><tr><td>跨位面協同原則</td><td>環境保護は跨位面協同で推進し、跨位面環境治理協力机制を構築する</td></tr></tbody></table><h2 id="第二節-環境保護の範囲" tabindex="-1">第二節 環境保護の範囲 <a class="header-anchor" href="#第二節-環境保護の範囲" aria-label="Permalink to &quot;第二節 環境保護の範囲&quot;">​</a></h2><p>本法が保護する環境範囲には、衡元宙内のすべての生態系と環境要素が含まれる：</p><ol><li><strong>大気環境</strong>: 各惑星の大気層、エネルギー層のエネルギー濃度と成分バランスを含む。</li><li><strong>水環境</strong>: 地表水、地下水、海洋、位面間エネルギー水域の水質と水量を含む。</li><li><strong>土壌環境</strong>: 陸地土壌、修練資源鉱脈の土質と肥沃度を含む。</li><li><strong>生物多様性</strong>: すべての動植物、微生物、奇特生命の種保護と生息地保護を含む。</li><li><strong>エネルギー環境</strong>: 天地霊気、本源エネルギー、法則碎片の濃度と分布バランスを含む。</li><li><strong>空間環境</strong>: 位面空間の安定性、空間裂隙、折りたたみ空間の環境安全を含む。</li><li><strong>意識域環境</strong>: 集団意識空間の情報清潔度と精神汚染防止を含む。</li></ol><h2 id="第三節-主要制度" tabindex="-1">第三節 主要制度 <a class="header-anchor" href="#第三節-主要制度" aria-label="Permalink to &quot;第三節 主要制度&quot;">​</a></h2><h3 id="一-環境影響評価制度" tabindex="-1">（一）環境影響評価制度 <a class="header-anchor" href="#一-環境影響評価制度" aria-label="Permalink to &quot;（一）環境影響評価制度&quot;">​</a></h3><p>環境に重大な影響を与える可能性のあるすべての開発建設プロジェクトは、着工前に環境影響評価を行わなければならない。評価内容には：プロジェクトの大気、水、土壌、生物、エネルギー、空間などの環境要素への影響、予防と緩和措置、環境リスク評価などが含まれる。環境影響評価に合格しなかったプロジェクトは着工建設できない。</p><h3 id="二-排出許可と総量制御制度" tabindex="-1">（二）排出許可と総量制御制度 <a class="header-anchor" href="#二-排出許可と総量制御制度" aria-label="Permalink to &quot;（二）排出許可と総量制御制度&quot;">​</a></h3><p>国家は汚染物排出に対して許可管理と総量制御を実施する。排出単位は排出許可証を取得しなければならず、許可証に規定された種類、濃度、総量に従って汚染物を排出する。国家は環境収容力に応じて各区域、各位面の汚染物排出総量を決定し、段階的に分解して実施する。</p><h3 id="三-生態保護紅線制度" tabindex="-1">（三）生態保護紅線制度 <a class="header-anchor" href="#三-生態保護紅線制度" aria-label="Permalink to &quot;（三）生態保護紅線制度&quot;">​</a></h3><p>国家は特殊な生態価値を有する区域に生態保護紅線を画定し、以下を含む：</p><table tabindex="0"><thead><tr><th>紅線類型</th><th>保護内容</th></tr></thead><tbody><tr><td>本源保護区</td><td>宇宙本源エネルギーの核心産出区域、すべての開発活動を禁止</td></tr><tr><td>種生息地</td><td>希少絶滅危惧種の核心生息地、破壊と干渉を禁止</td></tr><tr><td>生態屏障区</td><td>区域生態平衡を維持する鍵となる生態系、開発を制限</td></tr><tr><td>修練聖地</td><td>特殊な修練価値を有するエネルギー濃縮区、保護的利用を実施</td></tr><tr><td>位面交界帯</td><td>位面間の生態過渡帯、空間破壊的開発を禁止</td></tr></tbody></table><h3 id="四-環境監測と警報制度" tabindex="-1">（四）環境監測と警報制度 <a class="header-anchor" href="#四-環境監測と警報制度" aria-label="Permalink to &quot;（四）環境監測と警報制度&quot;">​</a></h3><p>国家は全宇宙をカバーする環境監測ネットワークを構築し、各環境要素の変化状況をリアルタイムで監視する。発生する可能性のある重大な環境汚染と生態破壊事件に対して、警報机制を構築し、適時に警報情報を発布し緊急応答を起動する。</p><h3 id="五-生態補償制度" tabindex="-1">（五）生態補償制度 <a class="header-anchor" href="#五-生態補償制度" aria-label="Permalink to &quot;（五）生態補償制度&quot;">​</a></h3><p>環境保護のために開発が制限された区域と群体は、生態補償を受ける権利を有する。生態補償資金は公共積立と資源開発収益から支出され、補償区域の経済発展と居住者の生活改善に用いられる。</p><h2 id="第四節-修練活動の環境規制" tabindex="-1">第四節 修練活動の環境規制 <a class="header-anchor" href="#第四節-修練活動の環境規制" aria-label="Permalink to &quot;第四節 修練活動の環境規制&quot;">​</a></h2><p>修練活動の環境への影響は衡元宙環境保護の特殊分野であり、本法は専門的に規制条項を設ける：</p><ol><li><strong>エネルギー採掘規制</strong>: 修練資源の採掘は持続可能原則に適合しなければならず、エネルギー枯渇を引き起こす破壊的採掘を禁止する。採掘量は区域エネルギーの自然回復速度を超えてはならない。</li><li><strong>修練廃棄物処理</strong>: 修練過程で発生するエネルギー残渣、廃棄丹薬、破損法器などは規定に従って処理しなければならず、随意に投棄してエネルギー汚染を引き起こすことを禁止する。</li><li><strong>高階修練環境評価</strong>: 高階修練者の突破と閉関は周辺環境に重大な影響を与える可能性があり、事前に環境評価を行い防護措置を講じなければならない。</li><li><strong>位面開発許可</strong>: 新位面の開発は環境評価と生態調査を経なければならず、生態保護方案を制定した後に実施できる。</li><li><strong>奇特生命生息地保護</strong>: 奇特生命の生息地は生態保護紅線に組み入れられ、許可のない探索と開発を禁止する。</li></ol><h2 id="第五節-法律責任" tabindex="-1">第五節 法律責任 <a class="header-anchor" href="#第五節-法律責任" aria-label="Permalink to &quot;第五節 法律責任&quot;">​</a></h2><p>本法の規定に違反する行為は、情状の軽重に応じて以下の責任を負う：</p><ul><li>環境影響評価に合格せずに擅自着工した場合、建設停止を命じ、原状回復し罰金を科す。</li><li>基準を超えて汚染物を排出した場合、期限付き治理を命じ罰金を科し、情状が深刻な場合は営業停止閉鎖を命じる。</li><li>生態保護紅線を破壊した場合、原状回復を命じ罰金を科し、情状が深刻な場合は刑事責任を追及する。</li><li>修練資源を破壊的に採掘した場合、違法所得を没収し罰金を科し、採掘許可を取り消す。</li><li>重大な環境汚染事故を引き起こした場合、賠償責任を負い、犯罪を構成する場合は刑事責任を追及する。</li><li>環境監督人員が職務を怠り、職権を濫用した場合、処分を与え、犯罪を構成する場合は刑事責任を追及する。</li></ul><h2 id="第六節-公衆参与と環境公益訴訟" tabindex="-1">第六節 公衆参与と環境公益訴訟 <a class="header-anchor" href="#第六節-公衆参与と環境公益訴訟" aria-label="Permalink to &quot;第六節 公衆参与と環境公益訴訟&quot;">​</a></h2><p>公衆は環境保護に参与する権利を有し、具体的な経路には以下が含まれる：</p><ol><li>環境影響評価プロジェクトに意見と提案を提出する。</li><li>環境汚染と生態破壊の行為に対して告発と苦情を行う。</li><li>法律に基づいて環境保護組織を設立し、環境監督と公益活動に参与する。</li><li>環境汚染、生態破壊が公共利益を損なう行為に対して、環境保護組織は共生法院に環境公益訴訟を提起できる。</li></ol><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>《環境保護法》はアンカー共生文明の持続可能な発展理念の法律保障である。それは環境影響評価、生態保護紅線、総量制御などの制度を構築することにより、環境保護をすべての開発と修練活動に融入させ、宇宙本源と生態系の持続可能性を確保し、万族共進のために永遠の生存根基を守る。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>40-共生宪法总纲 (共生憲法総綱)</li><li>39-住房与环境保障 (住宅と環境保障)</li><li>15-能量循环与转化法则 (エネルギー循環と転化法則)</li><li>53-奇特生命识别标准 (奇特生命識別基準)</li></ul>',34)])])}const p=a(e,[["render",i]]);export{u as __pageData,p as default};
